def reservoir_seed(stream, k, seed):
    if k < 0:
        return []
    import random
    random.seed(seed)
    n = len(stream)
    if k >= n:
        return stream[:]
    selected_indices = list(range(k))
    for i in range(k, n):
        if random.random() < k / (i + 1):
            replace_idx = random.randint(0, k - 1)
            selected_indices[replace_idx] = i
    result = [stream[i] for i in sorted(selected_indices)]
    return result
